    function getUserDataFolder() {
        var userDataFolder, bendScriptFolder, checkFolder;
        userDataFolder = Folder.userData;

        bendScriptFolder = Folder( userDataFolder.toString() + "/MDS/CrazyShapes/Pseudo" );
        if ( !bendScriptFolder.exists ) {
            checkFolder = bendScriptFolder.create();
            if ( !checkFolder ) {
                alert( "Error creating UI Master images" );
                bendScriptFolder = Folder.temp;
            }
        }
        return bendScriptFolder.toString();
    }

